from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if not all(field in raw for field in ("grid", "observations", "fill_value")):
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if not all(field in grid for field in ("width", "height", "cell_size")):
        return {"ok": False, "error": "bad grid"}

    for name in ("width", "height"):
        size = grid[name]
        if not isinstance(size, int) or not 1 <= size <= MAX_DIM:
            return {"ok": False, "error": "bad " + name}
    cell_size = grid["cell_size"]
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums, counts, degraded = {}, {}, {}
    dropped = rejected = saturated = 0
    for obs in observations:
        if not isinstance(obs, dict) or not all(
            isinstance(obs.get(field), int) for field in _OBS_FIELDS
        ):
            return {"ok": False, "error": "bad observation"}
        if not 0 <= obs["quality"] <= 100:
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        row = _place(obs["y"], cell_size, grid["height"])
        if row is None:
            dropped = dropped + 1
            continue
        col = _place(obs["x"], cell_size, grid["width"])
        if col is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    total = grid["width"] * grid["height"]
    cells = _averaged_rows(sums, counts, grid["width"], grid["height"], raw["fill_value"])
    flags = _flag_rows(counts, degraded, grid["width"], grid["height"])
    coverage = _coverage(counts, total)
    line = _summary_line(total, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _place(coord: int, cell_size: int, limit: int) -> int | None:
    """Map a coordinate to a cell index, clamping to the last cell within tolerance."""
    idx = coord // cell_size
    if 0 <= idx < limit:
        return idx
    if coord >= 0 and coord - limit * cell_size < cell_size // 2:
        return limit - 1
    return None


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, total_cells: int) -> int:
    return len(counts) * 100 // total_cells


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

